package com.bank.tfops;

import java.util.logging.Logger;

// Already managed. -replace forces destroy + recreate (config unchanged).
public class ManagedResource {
    private static final Logger log = Logger.getLogger(ManagedResource.class.getName());
    private final String address; private String realId; private boolean markedForReplace;

    public ManagedResource(String address, String realId) { this.address = address; this.realId = realId; }

    public void markReplace() { markedForReplace = true; log.warning(() -> "-replace marked: " + address + " (destroy+recreate next apply)"); }

    public void apply() {
        if (markedForReplace) {
            String old = realId;
            realId = address.replace('.', '-') + "-new";
            log.info(() -> "replace: destroyed " + old + " -> created " + realId);
            markedForReplace = false;
        } else {
            log.info(() -> "no-op: " + address + " unchanged (" + realId + ")");
        }
    }
    public String realId() { return realId; }
}
