package com.bank.tfops;

import java.util.*;
import java.util.logging.Logger;

// Adopts an unmanaged cloud resource into state (no create/destroy).
public class ImportTool {
    private static final Logger log = Logger.getLogger(ImportTool.class.getName());
    private final Set<String> state = new LinkedHashSet<>();

    public void importResource(String address, String realId) {
        state.add(address);
        log.info(() -> "import: " + address + " <- existing " + realId + " (now managed, NOT recreated)");
    }
    public boolean manages(String address) { return state.contains(address); }
}
