package com.bank.tfops;

import java.util.*;
import java.util.logging.Logger;

// In-configuration wiring: a module publishes outputs consumed as inputs.
public class ModuleOutputs {
    private static final Logger log = Logger.getLogger(ModuleOutputs.class.getName());
    private final Map<String,Object> outputs = new LinkedHashMap<>();

    public void publish(String key, Object value) { outputs.put(key, value); log.info(() -> "module output " + key + "=" + value); }
    public Object read(String key) { return outputs.get(key); }
}
