package com.bank.tfops;

import java.util.*;
import java.util.logging.Logger;

// Cross-stack: reads another configuration's published outputs via its state key.
public class RemoteStateReader {
    private static final Logger log = Logger.getLogger(RemoteStateReader.class.getName());
    private final Map<String, Map<String,Object>> stacks = new HashMap<>();

    public void publishStack(String stateKey, Map<String,Object> outputs) { stacks.put(stateKey, outputs); }
    public Object readOutput(String stateKey, String output) {
        Object v = stacks.getOrDefault(stateKey, Map.of()).get(output);
        log.info(() -> "terraform_remote_state[" + stateKey + "].outputs." + output + " = " + v);
        return v;
    }
}
