package com.bank.tfops;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TfOpsDemo {
    private static final Logger log = Logger.getLogger(TfOpsDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        // -replace: NAT gateway is managed but unhealthy -> destroy + recreate
        ManagedResource nat = new ManagedResource("aws_nat_gateway.bank", "nat-abc");
        nat.markReplace();
        nat.apply();

        // import: audit bucket was created by a contractor -> adopt, do NOT recreate
        ImportTool importer = new ImportTool();
        importer.importResource("aws_s3_bucket.audit", "nbi-audit-logs");
        log.info("audit bucket managed now=" + importer.manages("aws_s3_bucket.audit"));

        // in-config wiring: networking module output -> EKS module input
        ModuleOutputs networkMod = new ModuleOutputs();
        networkMod.publish("subnet_ids", List.of("subnet-a", "subnet-b"));
        Object subnets = networkMod.read("subnet_ids");
        log.info("EKS module input subnet_ids = " + subnets);

        // cross-stack: application stack reads networking stack outputs via remote state
        RemoteStateReader remote = new RemoteStateReader();
        remote.publishStack("networking/terraform.tfstate", Map.of("subnet_ids", List.of("prod-subnet-a","prod-subnet-b")));
        Object crossSubnets = remote.readOutput("networking/terraform.tfstate", "subnet_ids");

        log.info("prod EKS built on subnets " + crossSubnets + " (from networking remote state)");
        rajesh.debit(new BigDecimal("50000")); priya.credit(new BigDecimal("50000"));
        log.info("transfer SAV2001->CUR3001 Rs.50000 SUCCESS on EKS wired via module outputs + remote state");
    }
}
